import java.util.*;class Solution{public boolean isRectangleCover(int[][]r){long area=0;int x1=Integer.MAX_VALUE,y1=Integer.MAX_VALUE,x2=Integer.MIN_VALUE,y2=Integer.MIN_VALUE;Set<String>s=new HashSet<>();for(int[]a:r){x1=Math.min(x1,a[0]);y1=Math.min(y1,a[1]);x2=Math.max(x2,a[2]);y2=Math.max(y2,a[3]);area+=(long)(a[2]-a[0])*(a[3]-a[1]);String[]p={a[0]+","+a[1],a[0]+","+a[3],a[2]+","+a[1],a[2]+","+a[3]};for(String q:p)if(!s.add(q))s.remove(q);}return area==(long)(x2-x1)*(y2-y1)&&s.equals(new HashSet<>(Arrays.asList(x1+","+y1,x1+","+y2,x2+","+y1,x2+","+y2)));}}
